## Task: Create develop workflow main.ts with initialization phase
## Step: execute

Create .engin/workflows/develop/main.ts — the develop workflow module loaded dynamically by loadWorkflow().

This workflow must NOT use WorkflowStatusTracker (it has a fixed PHASE_ORDER incompatible with custom phases). It communicates entirely through StatusCallbacks.

Define DEVELOP_PHASES constant array: [{id:'initialization',label:'Initialization',icon:'🔧'},{id:'scouting',label:'Scouting',icon:'🔍'},{id:'scouting_review',label:'Scouting Review',icon:'📋'},{id:'planning',label:'Planning',icon:'📝'},{id:'plan_review',label:'Plan Review',icon:'👀'},{id:'implementing',label:'Implementing',icon:'🔨'},{id:'final_review',label:'Final Review',icon:'✅'},{id:'done',label:'Done',icon:'🎉'}]

Export default a WorkflowModule object:
{ name: 'develop', description: 'Multi-agent development workflow', async run(taskPrompt, options) { ... } }

The run function:
1. const { onStatus } = options;
2. Declare phases to frontend: onStatus?.onSidebarUpdate?.({ phases: DEVELOP_PHASES });
3. onStatus?.onWorkflowStart?.({ taskPrompt, resumed: false, workDir: options.workDir });
4. Phase: initialization. onStatus?.onPhaseStart?.({ phase: 'initialization', round: 1 });
5. Generate title via pi agent:
   - Resolve profiles: const profilesDirs = resolveProfilesDirs(options.cwd, 'develop'); const profiles = await loadProfilesFromDirs(profilesDirs); const profile = profiles.values().next().value;
   - If profile exists: create harness via createHarness({ profile, cwd: options.cwd, apiKeys: options.apiKeys, onAgentStatus: wire from onStatus }). Spawn agent notification. Prompt: 'Generate a concise title (3-6 words) summarizing this task. Return ONLY the title:\n\n' + taskPrompt. Get response. Dispose harness. Complete agent notification.
   - Fallback title: taskPrompt.slice(0, 50) + '...'
6. onStatus?.onSidebarUpdate?.({ title, indicator: '🔧' });
7. onStatus?.onPhaseComplete?.({ phase: 'initialization', durationMs: 0 });
8. Remaining phases are stubs (future work): for each phase after initialization (except 'done'), call onPhaseStart, update sidebar indicator, await a short delay, call onPhaseComplete.
9. Final phase 'done': onPhaseStart, update indicator to '🎉', onPhaseComplete.
10. onStatus?.onWorkflowComplete?.({ totalDurationMs: 0, agentCount: 1 });

Import from '@harms-haus/engin': WorkflowModule, WorkflowRunOptions, createHarness, loadProfilesFromDirs, resolveProfilesDirs.

Note: Import paths may need to reference the package since this file lives outside src/ in .engin/workflows/develop/. Use dynamic import or direct package import.

Verification: File is valid TypeScript. Can be tested with `engin run develop 'test prompt'`.

## Relevant Files
.engin/workflows/develop/main.ts

// ─── Re-exports from @earendil-works/pi-coding-agent ───────────────────────
export { AgentSession, AuthStorage, DefaultResourceLoader, SessionManager } from '@earendil-works/pi-coding-agent';
export type { ThinkingLevel };

// ─── Peer dependency re-exports (not re-exported by pi-coding-agent) ───────
import type { ThinkingLevel } from '@earendil-works/pi-agent-core';

export { getModel, parseJsonWithRepair } from '@earendil-works/pi-ai';
export type { Model } from '@earendil-works/pi-ai';

// ─── Agent Profile ──────────────────────────────────────────────────────────
export interface AgentProfile {
  id: string;
  name: string;
  provider: string;
  model: string;
  thinkingLevel: ThinkingLevel;
  systemPrompt: string;
  excludeTools: string[];
  includeTools: string[];
}

// ─── Task Tracking ──────────────────────────────────────────────────────────
export type TaskStatus = 'blocked' | 'ready' | 'claimed' | 'implementing' | 'reviewing' | 'done';

export interface Task {
  id: string;
  title: string;
  prompt: string;
  profile: string;
  files: string[];
  dependencies: string[];
  status: TaskStatus;
  assignedAgent?: string;
  result?: unknown;
  reviewFeedback?: string;
  isCode?: boolean;
}

// ─── Workflow Phases ────────────────────────────────────────────────────────
export type WorkflowPhase =
  | 'scouting'
  | 'scouting_review'
  | 'planning'
  | 'plan_review'
  | 'implementing'
  | 'final_review'
  | 'done';

export interface WorkflowState {
  taskPrompt: string;
  currentPhase: WorkflowPhase;
  completedPhases: WorkflowPhase[];
  tasks: Task[];
  /** Scouting reports stored as opaque values; consumers should cast to their specific schema type */
  scoutingReports: unknown[];
  /** Plan stored as opaque value; consumers should cast to their specific schema type */
  plan: unknown;
  research?: string;
  /** Plan review feedback text from the reviewer when a plan is rejected */
  planReviewFeedback?: string;
  /** Specific improvement suggestions from the plan reviewer */
  planReviewSuggestions?: string[];
  stats: {
    totalTokens: number;
    totalCost: number;
    agentCount: number;
  };
}

// ─── Audit Events ───────────────────────────────────────────────────────────
export type AuditEvent =
  | { type: 'agent_start'; agentId: string; profile: AgentProfile; taskId?: string; timestamp: string }
  | { type: 'agent_end'; agentId: string; result: unknown; taskId?: string; timestamp: string }
  | { type: 'decision'; agentId: string; decision: string; reasoning: string; taskId?: string; timestamp: string }
  | { type: 'structured_output'; agentId: string; output: unknown; taskId?: string; timestamp: string }
  | { type: 'error'; agentId: string; error: string; taskId?: string; timestamp: string };

// ─── Structured Output ──────────────────────────────────────────────────────
export interface StructuredOutputOptions {
  maxRetries: number;
  retryPrompt?: string;
}

// ─── Status Callbacks ──────────────────────────────────────────────────────
export interface WorkflowStatusCallbacks {
  onWorkflowStart?: (info: { taskPrompt: string; resumed: boolean; workDir: string }) => void;
  onPhaseStart?: (info: { phase: string; round: number }) => void;
  onPhaseComplete?: (info: { phase: string; durationMs: number }) => void;
  onAgentSpawn?: (info: { agentId: string; profile: string; phase: string; taskId?: string }) => void;
  onAgentComplete?: (info: { agentId: string; profile: string; phase: string; taskId?: string }) => void;
  onTaskStart?: (info: { taskId: string; title: string; agentId: string }) => void;
  onTaskComplete?: (info: { taskId: string; title: string }) => void;
  onTaskRejected?: (info: { taskId: string; title: string; reason: string }) => void;
  onDecision?: (info: { agentId: string; decision: string; reasoning: string; taskId?: string }) => void;
  onError?: (info: { agentId: string; error: string; phase: string; taskId?: string }) => void;
  onWorkflowComplete?: (info: { totalDurationMs: number; agentCount: number }) => void;
  onWorkflowFailed?: (info: { error: Error; phase: string }) => void;
  onSidebarUpdate?: (info: { title?: string; indicator?: string; phases?: Array<{ id: string; label: string; icon: string }> }) => void;
}

export type TurnContentBlock =
  | { type: 'text'; text: string }
  | { type: 'thinking'; thinking: string; redacted?: boolean }
  | { type: 'toolCall'; id: string; name: string; arguments: Record<string, unknown> };

export interface AgentStatusCallbacks {
  onTurnStart?: (info: { agentId: string; turn: number }) => void;
  onTurnEnd?: (info: {
    agentId: string;
    turn: number;
    tokens?: { input: number; output: number };
    contentBlocks?: TurnContentBlock[];
  }) => void;
  onToolCallStart?: (info: { agentId: string; toolName: string; toolCallId: string; arguments: Record<string, unknown> }) => void;
  onToolCallEnd?: (info: { agentId: string; toolName: string; toolCallId: string; isError: boolean }) => void;
}

export type StatusCallbacks = WorkflowStatusCallbacks & AgentStatusCallbacks;

// ─── Agent Loop Result ──────────────────────────────────────────────────────
export interface AgentLoopResult<T> {
  result: T;
  attempts: number;
  totalTokens: { input: number; output: number };
}

// ─── Workflow Run Options ──────────────────────────────────────────────────
export interface WorkflowRunOptions {
  cwd: string;
  workDir: string;
  maxConcurrentTasks?: number;
  apiKeys?: Record<string, string>;
  onStatus?: StatusCallbacks;
  /** Abort signal for cooperative cancellation (e.g. SIGINT) */
  signal?: AbortSignal;
}

// ─── Workflow Entry ───────────────────────────────────────────────────────
export interface WorkflowEntry {
  name: string;
  source: 'local' | 'global';
  path: string;
}

// ─── Workflow Module ────────────────────────────────────────────────────────
export interface WorkflowModule {
  run(taskPrompt: string, options: WorkflowRunOptions): Promise<void>;
  name?: string;
  description?: string;
}

// ─── Harness Creation ───────────────────────────────────────────────────────
export interface HarnessCreationOptions {
  profile: AgentProfile;
  cwd: string;
  apiKeys?: Record<string, string>;
  onAgentStatus?: AgentStatusCallbacks;
  sessionDir?: string;
  resumeSessionPath?: string;
}

import { readdir, stat } from 'node:fs/promises';
import { join } from 'node:path';
import { pathToFileURL } from 'node:url';
import { resolveWorkflowsDirs } from './config.js';
import type { WorkflowEntry, WorkflowModule } from './types.js';
import { validateWorkflowName } from './utils.js';

// ─── Cache ──────────────────────────────────────────────────────────────────

const workflowCache = new Map<string, WorkflowModule>();

/** Clears the module-level workflow cache. */
export function clearWorkflowCache(): void {
  workflowCache.clear();
}

// ─── loadWorkflow ───────────────────────────────────────────────────────────

/**
 * Dynamically loads a workflow module by name, searching local then global
 * workflow directories. Caches loaded modules by resolved absolute file path.
 */
export async function loadWorkflow(name: string, cwd: string): Promise<WorkflowModule> {
  // Validate workflow name to prevent path traversal
  validateWorkflowName(name);

  const dirs = resolveWorkflowsDirs(cwd);

  for (const dir of dirs) {
    const filePath = join(dir, name, 'main.ts');

    try {
      const fileStat = await stat(filePath);
      if (!fileStat.isFile()) continue;
    } catch {
      continue;
    }

    // Check cache first
    const cached = workflowCache.get(filePath);
    if (cached) return cached;

    const mod = await import(pathToFileURL(filePath).href);
    const workflow: WorkflowModule = mod.default ?? mod;

    if (typeof workflow.run !== 'function') {
      throw new Error(`Workflow '${name}' does not export a 'run' function.`);
    }

    workflowCache.set(filePath, workflow);
    return workflow;
  }

  throw new Error(`Workflow '${name}' not found.`);
}

// ─── listWorkflows ──────────────────────────────────────────────────────────

/**
 * Lists available workflow files across local and global directories.
 * Returns entries sorted by name, then by source (local first).
 */
export async function listWorkflows(cwd: string): Promise<WorkflowEntry[]> {
  const dirs = resolveWorkflowsDirs(cwd);
  const dirEntries: { dir: string; source: 'local' | 'global' }[] = [
    { dir: dirs[0], source: 'local' },
    { dir: dirs[1], source: 'global' },
  ];
  const results: WorkflowEntry[] = [];

  for (const { dir, source } of dirEntries) {
    let entries: string[];
    try {
      entries = await readdir(dir);
    } catch {
      // Directory does not exist — skip
      continue;
    }

    for (const entry of entries) {
      // Skip hidden directories
      if (entry.startsWith('.')) continue;

      const entryPath = join(dir, entry);

      // Only include directories
      try {
        const entryStat = await stat(entryPath);
        if (!entryStat.isDirectory()) continue;
      } catch {
        continue;
      }

      // Check that main.ts exists inside the directory
      const mainPath = join(entryPath, 'main.ts');
      try {
        const mainStat = await stat(mainPath);
        if (!mainStat.isFile()) continue;
      } catch {
        continue;
      }

      results.push({ name: entry, source, path: mainPath });
    }
  }

  // Sort by name, then by source (local first)
  results.sort((a, b) => {
    const nameCmp = a.name.localeCompare(b.name);
    if (nameCmp !== 0) return nameCmp;
    // local before global
    if (a.source === b.source) return 0;
    return a.source === 'local' ? -1 : 1;
  });

  return results;
}

// ─── Harness Factory ────────────────────────────────────────────────────────
import { getModel } from '@earendil-works/pi-ai';
import type { AgentSession } from '@earendil-works/pi-coding-agent';
import {
  type AgentSessionEvent,
  AuthStorage,
  createAgentSession,
  DefaultResourceLoader,
  SessionManager,
} from '@earendil-works/pi-coding-agent';

import { loadProfile } from './profile.js';
import type { HarnessCreationOptions, TurnContentBlock } from './types.js';
import { DEFAULT_TOOLS } from './utils.js';

// ─── Agent Event Types ──────────────────────────────────────────────────────

/* eslint-disable @typescript-eslint/no-explicit-any */
type AgentLevelEvent =
  | { type: 'turn_start' }
  | { type: 'turn_end'; message: { role: string; content?: any[]; usage?: { input: number; output: number } } }
  | { type: 'tool_execution_start'; toolName: string; toolCallId: string; args?: Record<string, unknown> }
  | { type: 'tool_execution_end'; toolName: string; toolCallId: string; isError: boolean };
/* eslint-enable @typescript-eslint/no-explicit-any */

// ─── createHarness ──────────────────────────────────────────────────────────

/**
 * Create an {@link AgentSession} wired to an in-memory session.
 *
 * Resolution steps:
 * 1. Resolve the model via {@link getModel}; throw if the provider/model
 *    combination is unknown.
 * 2. Create an {@link AuthStorage} via {@link AuthStorage.create} (loads
 *    credentials from `~/.pi/agent/auth.json`) and apply any caller-supplied
 *    `apiKeys` as runtime overrides.
 * 3. Build the tool allowlist/denylist from the profile configuration.
 * 4. Create a {@link DefaultResourceLoader} with the profile's system prompt.
 * 5. Construct the session via {@link createAgentSession}.
 * 6. Optionally subscribe to agent status callbacks.
 */
export async function createHarness(
  options: HarnessCreationOptions,
): Promise<{ session: AgentSession; sessionId: string; dispose: () => void }> {
  const { profile, cwd, apiKeys, onAgentStatus } = options;

  // 1. Model
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const model = getModel(profile.provider as any, profile.model as any);
  if (!model) {
    throw new Error(
      `Unknown model "${profile.model}" for provider "${profile.provider}". ` +
        `Check the provider and model identifiers.`,
    );
  }

  // 2. Auth storage — reads ~/.pi/agent/auth.json for stored credentials
  const authStorage = AuthStorage.create();
  if (apiKeys) {
    for (const [provider, key] of Object.entries(apiKeys)) {
      authStorage.setRuntimeApiKey(provider, key);
    }
  }

  // 3. Tools
  let builtTools: string[];
  if (profile.includeTools && profile.includeTools.length > 0) {
    // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
    builtTools = [...DEFAULT_TOOLS].filter((name) => profile.includeTools!.includes(name));
  } else {
    builtTools = [...DEFAULT_TOOLS];
  }
  if (profile.excludeTools && profile.excludeTools.length > 0) {
    // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
    builtTools = builtTools.filter((name) => !profile.excludeTools!.includes(name));
  }

  // 4. Resource loader
  const resourceLoader = new DefaultResourceLoader({
    cwd,
    agentDir: cwd,
    systemPromptOverride: () => profile.systemPrompt,
  });
  await resourceLoader.reload();

  // 5. Session
  let sessionManager;
  if (options.resumeSessionPath) {
    sessionManager = SessionManager.open(options.resumeSessionPath, undefined, cwd);
  } else if (options.sessionDir) {
    sessionManager = SessionManager.create(cwd, options.sessionDir);
  } else {
    sessionManager = SessionManager.inMemory(cwd);
  }
  const { session } = await createAgentSession({
    sessionManager,
    model,
    thinkingLevel: profile.thinkingLevel,
    tools: builtTools,
    resourceLoader,
    authStorage,
  });

  const sessionId = session.sessionId;

  // 6. Subscribe to agent status callbacks (if any handlers provided)
  let unsubscribe: (() => void) | undefined;
  if (
    onAgentStatus &&
    (onAgentStatus.onTurnStart ||
      onAgentStatus.onTurnEnd ||
      onAgentStatus.onToolCallStart ||
      onAgentStatus.onToolCallEnd)
  ) {
    let turnCount = 0;
    unsubscribe = session.subscribe((event: AgentSessionEvent) => {
      const e = event as AgentLevelEvent;
      if (e.type === 'turn_start') {
        onAgentStatus.onTurnStart?.({
          agentId: sessionId,
          turn: ++turnCount,
        });
      } else if (e.type === 'turn_end') {
        const isAssistant = e.message?.role === 'assistant';
        const usage = isAssistant ? e.message?.usage : undefined;
        let contentBlocks: TurnContentBlock[] | undefined;
        if (isAssistant && e.message.content) {
          contentBlocks = [];
          // Map only the block types supported by TurnContentBlock.
          // Unrecognized types (e.g., future upstream additions) are intentionally skipped.
          for (const block of e.message.content) {
            if (block.type === 'text') {
              contentBlocks.push({ type: 'text', text: block.text });
            } else if (block.type === 'thinking') {
              contentBlocks.push({ type: 'thinking', thinking: block.thinking, redacted: block.redacted });
            } else if (block.type === 'toolCall') {
              contentBlocks.push({ type: 'toolCall', id: block.id, name: block.name, arguments: block.arguments });
            }
          }
        }
        onAgentStatus.onTurnEnd?.({
          agentId: sessionId,
          turn: turnCount,
          tokens: usage ? { input: usage.input, output: usage.output } : undefined,
          contentBlocks,
        });
      } else if (e.type === 'tool_execution_start') {
        onAgentStatus.onToolCallStart?.({
          agentId: sessionId,
          toolName: e.toolName,
          toolCallId: e.toolCallId,
          arguments: e.args ?? {},
        });
      } else if (e.type === 'tool_execution_end') {
        onAgentStatus.onToolCallEnd?.({
          agentId: sessionId,
          toolName: e.toolName,
          toolCallId: e.toolCallId,
          isError: e.isError ?? false,
        });
      }
    });
  }

  const dispose = () => {
    unsubscribe?.();
    session.dispose();
  };

  return { session, sessionId, dispose };
}

// ─── createHarnessFromProfile ───────────────────────────────────────────────

/**
 * Convenience wrapper that loads an {@link AgentProfile} from a directory
 * and delegates to {@link createHarness}.
 */
export async function createHarnessFromProfile(
  dirPath: string,
  profileId: string,
  options: Omit<HarnessCreationOptions, 'profile'>,
): Promise<{ session: AgentSession; sessionId: string; dispose: () => void }> {
  const profile = await loadProfile(dirPath, profileId);
  return createHarness({ ...options, profile });
}

import matter from 'gray-matter';
import { readdir, readFile, stat } from 'node:fs/promises';
import { basename, join } from 'node:path';
import type { AgentProfile, ThinkingLevel } from './types.js';

const VALID_THINKING_LEVELS: readonly ThinkingLevel[] = ['off', 'minimal', 'low', 'medium', 'high', 'xhigh'];

/**
 * Module-level cache for loaded profiles, keyed by resolved directory path.
 * Profiles are unlikely to change during a workflow run, so caching avoids
 * redundant disk reads on every agent invocation.
 */
const profileCache = new Map<string, Map<string, AgentProfile>>();

function isThinkingLevel(value: unknown): value is ThinkingLevel {
  return VALID_THINKING_LEVELS.includes(value as ThinkingLevel);
}

/**
 * Parse a markdown file with frontmatter into an AgentProfile.
 *
 * Expected frontmatter fields:
 *   - name?       (defaults to filename without .md)
 *   - provider    (required)
 *   - model       (required)
 *   - thinkingLevel? (defaults to "medium")
 *   - excludeTools?  (defaults to [])
 *   - includeTools?  (defaults to [])
 *
 * The body (content after frontmatter) becomes the system prompt.
 */
export function parseProfile(content: string, filename: string): AgentProfile {
  const { data, content: body } = matter(content);

  const id = basename(filename, '.md');
  const name = (data.name as string | undefined) ?? id;

  if (data.provider == null || data.provider === '') {
    throw new Error(`Profile "${id}" is missing required frontmatter field "provider".`);
  }
  if (data.model == null || data.model === '') {
    throw new Error(`Profile "${id}" is missing required frontmatter field "model".`);
  }

  let thinkingLevel: ThinkingLevel = 'medium';
  if (data.thinkingLevel != null) {
    if (!isThinkingLevel(data.thinkingLevel)) {
      throw new Error(
        `Profile "${id}" has invalid thinkingLevel "${data.thinkingLevel}". ` +
          `Valid values: ${VALID_THINKING_LEVELS.join(', ')}.`,
      );
    }
    thinkingLevel = data.thinkingLevel;
  }

  return {
    id,
    name,
    provider: data.provider as string,
    model: data.model as string,
    thinkingLevel,
    systemPrompt: body.trim(),
    excludeTools: (data.excludeTools as string[] | undefined) ?? [],
    includeTools: (data.includeTools as string[] | undefined) ?? [],
  };
}

/**
 * Load all .md agent profiles from a directory.
 * Returns a Map keyed by profile id (filename without .md).
 * Results are cached in-memory — repeated calls with the same directory
 * return the cached Map without hitting disk.
 * Throws if the directory does not exist.
 */
export async function loadProfiles(dirPath: string): Promise<Map<string, AgentProfile>> {
  const cached = profileCache.get(dirPath);
  if (cached) {
    return cached;
  }

  let dirStat;
  try {
    dirStat = await stat(dirPath);
  } catch {
    throw new Error(`Directory does not exist: ${dirPath}`);
  }

  if (!dirStat.isDirectory()) {
    throw new Error(`Path is not a directory: ${dirPath}`);
  }

  const entries = await readdir(dirPath);
  const mdFiles = entries.filter((entry) => entry.endsWith('.md'));

  const profiles = new Map<string, AgentProfile>();

  for (const file of mdFiles) {
    const filePath = join(dirPath, file);
    const content = await readFile(filePath, 'utf-8');
    const profile = parseProfile(content, file);
    profiles.set(profile.id, profile);
  }

  profileCache.set(dirPath, profiles);
  return profiles;
}

/**
 * Load a single profile by id from a directory.
 * Uses the cached directory listing when available.
 * Throws if the profile is not found.
 */
export async function loadProfile(dirPath: string, profileId: string): Promise<AgentProfile> {
  const profiles = await loadProfiles(dirPath);
  const profile = profiles.get(profileId);

  if (!profile) {
    throw new Error(`Profile "${profileId}" not found in directory: ${dirPath}`);
  }

  return profile;
}

/**
 * Load a single profile directly from a .md file path.
 * Bypasses the directory cache — use when you know the exact file.
 * Throws if the file does not exist or is invalid.
 */
export async function loadProfileSingle(filePath: string): Promise<AgentProfile> {
  let content: string;
  try {
    content = await readFile(filePath, 'utf-8');
  } catch {
    throw new Error(`Profile file does not exist: ${filePath}`);
  }
  return parseProfile(content, basename(filePath));
}

/**
 * Load and merge agent profiles from multiple directories.
 *
 * Directories are processed in reverse order (last entry first) so that
 * entries earlier in the array ("local" dirs) naturally override later
 * entries ("global" dirs) when profile IDs collide.
 *
 * Directories that do not exist or are not directories are silently skipped.
 * Any other error (e.g. a malformed .md file) is re-thrown.
 *
 * The merged result is NOT cached — only the per-directory results from
 * `loadProfiles` use the module-level cache.
 */
export async function loadProfilesFromDirs(dirs: string[]): Promise<Map<string, AgentProfile>> {
  const merged = new Map<string, AgentProfile>();

  for (let i = dirs.length - 1; i >= 0; i--) {
    try {
      const profiles = await loadProfiles(dirs[i]);
      for (const [id, profile] of profiles) {
        merged.set(id, profile);
      }
    } catch (err: unknown) {
      // Skip directories that don't exist or aren't directories.
      // Primary check: Node.js system error codes from stat()/readdir().
      // Fallback check: custom error messages thrown by loadProfiles.
      if (
        (err instanceof Error &&
          'code' in err &&
          ((err as NodeJS.ErrnoException).code === 'ENOENT' || (err as NodeJS.ErrnoException).code === 'ENOTDIR')) ||
        (err instanceof Error &&
          (err.message.startsWith('Directory does not exist') || err.message.startsWith('Path is not a directory')))
      ) {
        continue;
      }
      throw err;
    }
  }

  return merged;
}

/**
 * Clear the in-memory profile cache.
 * Call this to force a fresh read on the next loadProfiles() call.
 */
export function clearProfileCache(): void {
  profileCache.clear();
}

import { parse } from 'dotenv';
import { readFileSync } from 'node:fs';
import { mkdir } from 'node:fs/promises';
import { homedir } from 'node:os';
import { join } from 'node:path';
import { isEnoentError, validateWorkflowName } from './utils.js';

/**
 * Returns the global configuration directory for engin.
 * Uses $XDG_CONFIG_HOME/engin if XDG_CONFIG_HOME is set and non-empty,
 * otherwise falls back to ~/.config/engin.
 */
export function getGlobalConfigDir(): string {
  const xdg = process.env.XDG_CONFIG_HOME;
  if (xdg && xdg.length > 0) {
    return join(xdg, 'engin');
  }
  return join(homedir(), '.config', 'engin');
}

/**
 * Returns the local (project-level) configuration directory for engin.
 */
export function getLocalConfigDir(cwd: string): string {
  return join(cwd, '.engin');
}

/**
 * Returns profile directories in override-priority order (local first).
 * Does NOT check whether the directories exist.
 *
 * When `workflowName` is a non-empty string, returns workflow-scoped
 * profile directories under `workflows/<workflowName>/profiles`.
 * When `workflowName` is omitted or empty, returns an empty array.
 */
export function resolveProfilesDirs(cwd: string, workflowName?: string): string[] {
  if (!workflowName || workflowName.length === 0) {
    return [];
  }
  validateWorkflowName(workflowName);
  return [
    join(getLocalConfigDir(cwd), 'workflows', workflowName, 'profiles'),
    join(getGlobalConfigDir(), 'workflows', workflowName, 'profiles'),
  ];
}

/**
 * Returns workflow directories in override-priority order (local first).
 * Does NOT check whether the directories exist.
 */
export function resolveWorkflowsDirs(cwd: string): string[] {
  return [join(getLocalConfigDir(cwd), 'workflows'), join(getGlobalConfigDir(), 'workflows')];
}

/**
 * Returns the default working directory for a named workflow.
 */
export function getDefaultWorkDir(cwd: string, workflowName: string): string {
  return join(getLocalConfigDir(cwd), 'work', workflowName);
}

/**
 * Recursively creates a directory. Re-throws any errors.
 */
export async function ensureDir(dirPath: string): Promise<void> {
  await mkdir(dirPath, { recursive: true });
}

/**
 * Result of loading .env files from global and local config directories.
 */
export interface LoadEnvResult {
  loadedFiles: string[]; // paths of .env files that existed and were parsed
  skippedFiles: string[]; // paths of .env files that did not exist
  keysSet: string[]; // env var names actually written to process.env (excluding already-set keys)
}

/** Environment variable names that are never loaded from .env files due to security risks. */
const BLOCKED_ENV_KEYS = new Set([
  'NODE_OPTIONS',
  'NODE_TLS_REJECT_UNAUTHORIZED',
  'NODE_EXTRA_CA_CERTS',
  'LD_PRELOAD',
  'LD_LIBRARY_PATH',
  'PATH',
  'HOME',
  'SHELL',
]);

/**
 * Loads .env files from global and local config directories, merges them
 * (local overrides global), and sets keys into process.env only if they are
 * not already defined.
 *
 * Synchronous because .env loading must complete before any command dispatch.
 */
export function loadEnvFiles(cwd: string): LoadEnvResult {
  const globalEnvPath = join(getGlobalConfigDir(), '.env');
  const localEnvPath = join(getLocalConfigDir(cwd), '.env');

  const loadedFiles: string[] = [];
  const skippedFiles: string[] = [];
  let globalVars: Record<string, string> = {};
  let localVars: Record<string, string> = {};

  for (const envPath of [globalEnvPath, localEnvPath]) {
    try {
      const content = readFileSync(envPath, 'utf-8');
      const parsed = parse(content);
      loadedFiles.push(envPath);
      if (envPath === globalEnvPath) {
        globalVars = parsed;
      } else {
        localVars = parsed;
      }
    } catch (err: unknown) {
      if (isEnoentError(err)) {
        skippedFiles.push(envPath);
      } else {
        throw err;
      }
    }
  }

  const merged = { ...globalVars, ...localVars };
  const keysSet: string[] = [];

  for (const [key, value] of Object.entries(merged)) {
    if (BLOCKED_ENV_KEYS.has(key)) {
      continue;
    }
    if (!(key in process.env)) {
      process.env[key] = value;
      keysSet.push(key);
    }
  }

  return { loadedFiles, skippedFiles, keysSet };
}

